def cmp_semver(a, b):
    def _parse(v):
        v = v.split("+", 1)[0]
        if "-" in v:
            core, pre = v.split("-", 1)
            if not pre:
                pre = None
        else:
            core, pre = v, None

        parts = core.split(".")
        nums = []
        for i in range(3):
            nums.append(int(parts[i]) if i < len(parts) and parts[i] != "" else 0)

        return nums[0], nums[1], nums[2], pre

    def _cmp_pre(x, y):
        if x is None and y is None:
            return 0
        if x is None:
            return 1
        if y is None:
            return -1

        xs = x.split(".")
        ys = y.split(".")

        for xs_id, ys_id in zip(xs, ys):
            x_num = xs_id.isdigit()
            y_num = ys_id.isdigit()

            if x_num and y_num:
                xi = int(xs_id)
                yi = int(ys_id)
                if xi < yi:
                    return -1
                if xi > yi:
                    return 1
            elif x_num:
                return -1
            elif y_num:
                return 1
            else:
                if xs_id < ys_id:
                    return -1
                if xs_id > ys_id:
                    return 1

        if len(xs) < len(ys):
            return -1
        if len(xs) > len(ys):
            return 1
        return 0

    am, an, ap, apre = _parse(a)
    bm, bn, bp, bpre = _parse(b)

    for x, y in ((am, bm), (an, bn), (ap, bp)):
        if x < y:
            return -1
        if x > y:
            return 1

    return _cmp_pre(apre, bpre)

