def parse_range(header, size):
    def _is_digits(s):
        return bool(s) and all(c in "0123456789" for c in s)

    if isinstance(header, bytes):
        try:
            header = header.decode("latin-1")
        except Exception:
            return None
    if not isinstance(header, str):
        return None

    try:
        size = int(size)
    except Exception:
        return None
    if size < 0:
        return None

    h = header.strip()
    if not h.lower().startswith("bytes="):
        return None

    value = h[6:].strip()
    if not value:
        return None

    result = []
    for part in value.split(","):
        part = part.strip()
        if not part:
            return None
        if "-" not in part:
            return None

        left, right = part.split("-", 1)
        left = left.strip()
        right = right.strip()

        if left == "":
            if not _is_digits(right):
                return None
            suffix = int(right)
            if suffix <= 0 or size == 0:
                continue
            start = size - suffix
            if start < 0:
                start = 0
            end = size - 1
            if start >= size:
                continue
            result.append((start, end))
        else:
            if not _is_digits(left):
                return None
            start = int(left)
            if right == "":
                end = size - 1
            else:
                if not _is_digits(right):
                    return None
                end = int(right)

            if start >= size:
                continue
            if end >= size:
                end = size - 1
            if start > end:
                continue
            result.append((start, end))

    return result if result else None

