        first, second = (src, dst) if src < dst else (dst, src)
        with locks[first], locks[second]:
            if accounts[src] >= amount:
                accounts[src] -= amount
                accounts[dst] += amount

    threads = []
    for src, dst, amount in ops:
        t = threading.Thread(target=do_transfer, args=(src, dst, amount))
        threads.append(t)
        t.start()

    for t in threads:
        t.join()

    return accounts

